import{_ as e,o as n,c as i,a3 as a}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"四种均匀性的等价关系","description":"","frontmatter":{"translationSource":{"title":"四种均匀性的等价关系","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0UWq18LU5z08cMqBDGHmT2","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/equivalence-relations-between-four-types-of-uniformity"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/equivalence-relations-between-four-types-of-uniformity"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/equivalence-relations-between-four-types-of-uniformity"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/equivalence-relations-between-four-types-of-uniformity"}]]},"headers":[],"relativePath":"zh/equivalence-relations-between-four-types-of-uniformity.md","filePath":"zh/page-0UWq18LU5z08cMqBDGHmT2.md"}'),l={name:"zh/equivalence-relations-between-four-types-of-uniformity.md"};function p(o,t,r,_,c,d){return n(),i("div",null,[...t[0]||(t[0]=[a('<div class="logistics-content"><span class="logistics-source-anchor" id="四种均匀性的等价关系" aria-hidden="true"></span><h1 id="四种均匀性的等价关系" tabindex="-1">四种均匀性的等价关系 <a class="header-anchor" href="#四种均匀性的等价关系" aria-label="Permalink to &quot;四种均匀性的等价关系&quot;">​</a></h1><blockquote><p>源页面 ID：<code>0UWq18LU5z08cMqBDGHmT2</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=0UWq18LU5z08cMqBDGHmT2" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>定义（统一符号）：</p><p>Bresenham-M均匀：对所有 n 属于 Z+，|S_cum(n) - d * n| &lt; M</p><p>Beatty-M均匀：对所有 i,j 属于 Z+，|S_cum(i,j) - (j-i) * d| &lt; M</p><p>其中 S_cum(i,j) = S_cum(j) - S_cum(i)</p><p>Cipolla-M物品均匀：sup_n(S_cum(n) - d * n) - inf_n(S_cum(n) - d * n) &lt; M</p><p>Cipolla-M时间均匀：sup_n(t_n - n * T_avg) - inf_n(t_n - n * T_avg) &lt; M</p><p>注意 T_avg = 1/d</p><p>定理1：Bresenham-M均匀 等价于 Beatty-2M均匀（双向蕴含，常数因子2）</p><p>证明：</p><p>(=&gt;)：|S_cum(j) - j * d| &lt; M 且 |S_cum(i) - i * d| &lt; M，故：</p><p>|S_cum(i,j) - (j-i)d| &lt;= |S_cum(j)-j * d| + |S_cum(i)-i * d| &lt; 2M</p><p>(&lt;=)：取 i=1 即得Bresenham-M均匀。</p><p>定理2：Beatty-M均匀 等价于 Cipolla-M物品均匀（等价，常数一致）</p><p>证明：</p><p>(=&gt;)：由Beatty-M，任意两点偏差 |E(i) - E(j)| = |S_cum(i,j) - (j-i)d| &lt; M，故极差 &lt; M。</p><p>(&lt;=)：若极差 &lt; M，则对任意 i,j，|E(j) - E(i)| &lt; M，即 |S_cum(i,j) - (j-i)d| &lt; M。</p><p>定理3：Cipolla-M物品均匀 等价于 Cipolla-(M/d + 1) 时间均匀（双向蕴含，常数转换）</p><p>证明：</p><p>(=&gt;)：由 S_cum(n) = k 当 t_k &lt;= n &lt; t_{k+1}，有 t_k - k * T_avg = T_avg(k * d - t_k * d) = (1/d)(k - S_cum(t_k))。</p><p>利用 t_n - n/d 与 S_cum(n) - n * d 的对偶关系，可证：</p><p>sup_n(t_n - n/d) - inf_n(t_n - n/d) &lt;= (1/d) * M</p><p>(&lt;=)：对于 n 属于 [t_k, t_{k+1})，S_cum(n) = k，有：</p><p>t_k - k * T_avg &lt;= n * T_avg - S_cum(n) * T_avg &lt; t_{k+1} - k * T_avg = (t_{k+1} - (k+1)T_avg) + T_avg</p><p>故时间均匀 =&gt; 物品均匀，且 M_item &lt;= d * M_time + 1。</p><p>证明由madSUN完成，由群内多人审阅正确性，由jnk进行了标准名词化</p></div>',1)])])}const m=e(l,[["render",p]]);export{u as __pageData,m as default};
